# TCP/IP Server in C

Here's a complete TCP/IP server implementation in C with detailed comments:

## Basic TCP Server

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <errno.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define MAX_CONNECTIONS 5

int main(int argc, char *argv[])
{
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // ========================
    // 1. CREATE SOCKET
    // ========================
    // AF_INET     = IPv4
    // SOCK_STREAM = TCP
    // 0           = default protocol
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }
    printf("[+] Socket created successfully.\n");

    // ========================
    // 2. SET SOCKET OPTIONS (optional but recommended)
    // ========================
    // SO_REUSEADDR allows reuse of the port immediately after the server stops
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // ========================
    // 3. CONFIGURE SERVER ADDRESS
    // ========================
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family      = AF_INET;         // IPv4
    server_addr.sin_addr.s_addr = INADDR_ANY;      // Bind to all interfaces
    server_addr.sin_port        = htons(PORT);      // Convert to network byte order

    // ========================
    // 4. BIND SOCKET TO ADDRESS
    // ========================
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("[+] Bound to port %d.\n", PORT);

    // ========================
    // 5. LISTEN FOR CONNECTIONS
    // ========================
    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("[+] Server listening on port %d...\n", PORT);

    // ========================
    // 6. ACCEPT AND HANDLE CONNECTIONS (loop)
    // ========================
    while (1) {
        client_len = sizeof(client_addr);

        // Accept incoming connection
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        // Print client info
        printf("[+] Client connected: %s:%d\n",
               inet_ntoa(client_addr.sin_addr),
               ntohs(client_addr.sin_port));

        // Send welcome message
        const char *welcome_msg = "Welcome to the TCP Server!\n";
        send(client_fd, welcome_msg, strlen(welcome_msg), 0);

        // ========================
        // 7. COMMUNICATE WITH CLIENT
        // ========================
        while (1) {
            // Clear buffer
            memset(buffer, 0, BUFFER_SIZE);

            // Receive data from client
            bytes_read = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

            if (bytes_read < 0) {
                perror("Receive failed");
                break;
            }
            else if (bytes_read == 0) {
                printf("[-] Client disconnected: %s:%d\n",
                       inet_ntoa(client_addr.sin_addr),
                       ntohs(client_addr.sin_port));
                break;
            }

            // Null-terminate received data
            buffer[bytes_read] = '\0';

            // Remove trailing newline
            if (buffer[bytes_read - 1] == '\n')
                buffer[bytes_read - 1] = '\0';

            printf("[Client %s:%d]: %s\n",
                   inet_ntoa(client_addr.sin_addr),
                   ntohs(client_addr.sin_port),
                   buffer);

            // Check for "quit" command
            if (strncmp(buffer, "quit", 4) == 0) {
                printf("[-] Client requested disconnect.\n");
                const char *bye_msg = "Goodbye!\n";
                send(client_fd, bye_msg, strlen(bye_msg), 0);
                break;
            }

            // Check for "shutdown" command
            if (strncmp(buffer, "shutdown", 8) == 0) {
                printf("[!] Server shutting down...\n");
                const char *shutdown_msg = "Server shutting down.\n";
                send(client_fd, shutdown_msg, strlen(shutdown_msg), 0);
                close(client_fd);
                close(server_fd);
                exit(EXIT_SUCCESS);
            }

            // Echo back to client (with prefix)
            char response[BUFFER_SIZE + 20];
            snprintf(response, sizeof(response), "Server echo: %s\n", buffer);
            send(client_fd, response, strlen(response), 0);
        }

        // ========================
        // 8. CLOSE CLIENT CONNECTION
        // ========================
        close(client_fd);
    }

    // ========================
    // 9. CLOSE SERVER SOCKET
    // ========================
    close(server_fd);

    return 0;
}
```

