## Multi-Client Server (using `fork()`)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define MAX_CONNECTIONS 10

// Signal handler to reap zombie child processes
void sigchld_handler(int sig)
{
    (void)sig; // suppress unused warning
    while (waitpid(-1, NULL, WNOHANG) > 0);
}

// Function to handle each client
void handle_client(int client_fd, struct sockaddr_in client_addr)
{
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    printf("[+] [PID %d] Handling client %s:%d\n",
           getpid(),
           inet_ntoa(client_addr.sin_addr),
           ntohs(client_addr.sin_port));

    // Send welcome message
    const char *welcome = "Welcome! Type 'quit' to disconnect.\n";
    send(client_fd, welcome, strlen(welcome), 0);

    while (1) {
        memset(buffer, 0, BUFFER_SIZE);
        bytes_read = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

        if (bytes_read <= 0) {
            printf("[-] [PID %d] Client %s:%d disconnected.\n",
                   getpid(),
                   inet_ntoa(client_addr.sin_addr),
                   ntohs(client_addr.sin_port));
            break;
        }

        buffer[bytes_read] = '\0';

        // Remove newline
        char *newline = strchr(buffer, '\n');
        if (newline) *newline = '\0';

        printf("[Client %s:%d]: %s\n",
               inet_ntoa(client_addr.sin_addr),
               ntohs(client_addr.sin_port),
               buffer);

        if (strncmp(buffer, "quit", 4) == 0) {
            send(client_fd, "Goodbye!\n", 9, 0);
            break;
        }

        // Echo response
        char response[BUFFER_SIZE + 20];
        snprintf(response, sizeof(response), "Echo: %s\n", buffer);
        send(client_fd, response, strlen(response), 0);
    }

    close(client_fd);
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;
    pid_t pid;

    // Set up SIGCHLD handler
    struct sigaction sa;
    sa.sa_handler = sigchld_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGCHLD, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    // Configure address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family      = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port        = htons(PORT);

    // Bind
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listen
    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("[+] Multi-client server listening on port %d...\n", PORT);

    // Accept loop
    while (1) {
        client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);

        if (client_fd < 0) {
            if (errno == EINTR)
                continue; // Interrupted by signal, retry
            perror("Accept failed");
            continue;
        }

        printf("[+] New connection from %s:%d\n",
               inet_ntoa(client_addr.sin_addr),
               ntohs(client_addr.sin_port));

        // Fork a child process for each client
        pid = fork();

        if (pid < 0) {
            perror("Fork failed");
            close(client_fd);
            continue;
        }
        else if (pid == 0) {
            // Child process
            close(server_fd);   // Child doesn't need the listener
            handle_client(client_fd, client_addr);
            // handle_client calls exit(), but just in case:
            exit(EXIT_SUCCESS);
        }
        else {
            // Parent process
            close(client_fd);   // Parent doesn't need the client socket
        }
    }

    close(server_fd);
    return 0;
}
